#include <iostream>
#include <type_traits>
using namespace std;

int main() {
    int x = 1;
    const int cx = 2;
    int& rx = x;
    (void)x;

    auto a = cx;              // const 被丢弃
    auto& b = cx;             // 保留 const 与引用
    const auto& c = cx;       // 显式 const 引用
    auto d = rx;              // 引用被丢弃（发生拷贝）
    auto& e = rx;             // 保留引用

    cout << boolalpha;
    cout << "auto a = cx        是 int ?        " << is_same_v<decltype(a), int> << "\n";
    cout << "auto& b = cx       是 const int& ? " << is_same_v<decltype(b), const int&> << "\n";
    cout << "const auto& c = cx 是 const int& ? " << is_same_v<decltype(c), const int&> << "\n";
    cout << "auto d = rx        是 int ?        " << is_same_v<decltype(d), int> << "\n";
    cout << "auto& e = rx       是 int& ?       " << is_same_v<decltype(e), int&> << "\n";
    (void)b; (void)c; (void)d; (void)e;
}
